const TZ = 'Asia/Dubai';
const TZ_OFFSET = '+04:00';

function pad(n) {
  return String(n).padStart(2, '0');
}

function dubaiNowParts() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date()).reduce((acc, p) => {
    acc[p.type] = p.value;
    return acc;
  }, {});
  return { year: Number(parts.year), month: Number(parts.month), day: Number(parts.day) };
}

function daysInMonth(year, month) {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

function addDaysISO(dateISO, days) {
  let [year, month, day] = dateISO.split('-').map(Number);
  day += days;
  while (day > daysInMonth(year, month)) {
    day -= daysInMonth(year, month);
    month += 1;
    if (month > 12) {
      month = 1;
      year += 1;
    }
  }
  while (day < 1) {
    month -= 1;
    if (month < 1) {
      month = 12;
      year -= 1;
    }
    day += daysInMonth(year, month);
  }
  return `${year}-${pad(month)}-${pad(day)}`;
}

function todayISO() {
  const p = dubaiNowParts();
  return `${p.year}-${pad(p.month)}-${pad(p.day)}`;
}

const MONTHS = {
  january: '01', jan: '01',
  february: '02', feb: '02',
  march: '03', mar: '03',
  april: '04', apr: '04',
  may: '05',
  june: '06', jun: '06',
  july: '07', jul: '07',
  august: '08', aug: '08',
  september: '09', sept: '09', sep: '09',
  october: '10', oct: '10',
  november: '11', nov: '11',
  december: '12', dec: '12'
};

function parseDateToISO(dateText) {
  const value = String(dateText || '').trim();
  const lower = value.toLowerCase().replace(/[,]+/g, ' ').replace(/\s+/g, ' ').trim();
  if (!lower) throw new Error('Missing date');

  if (lower === 'today') return todayISO();
  if (lower === 'tomorrow') return addDaysISO(todayISO(), 1);

  let m = lower.match(/^(\d{4})[-.\/](\d{1,2})[-.\/](\d{1,2})$/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;

  m = lower.match(/^(\d{1,2})[-.\/](\d{1,2})[-.\/](\d{4})$/);
  if (m) return `${m[3]}-${pad(m[2])}-${pad(m[1])}`;

  m = lower.match(/^(?:[a-z]+day\s+)?(\d{1,2})\s+([a-z]+)\s+(\d{4})$/);
  if (m && MONTHS[m[2]]) return `${m[3]}-${MONTHS[m[2]]}-${pad(m[1])}`;

  m = lower.match(/^(?:[a-z]+day\s+)?([a-z]+)\s+(\d{1,2})\s+(\d{4})$/);
  if (m && MONTHS[m[1]]) return `${m[3]}-${MONTHS[m[1]]}-${pad(m[2])}`;

  const current = dubaiNowParts();

  m = lower.match(/^(?:[a-z]+day\s+)?(\d{1,2})\s+([a-z]+)$/);
  if (m && MONTHS[m[2]]) {
    let year = current.year;
    let candidate = `${year}-${MONTHS[m[2]]}-${pad(m[1])}`;
    if (candidate < todayISO()) {
      year += 1;
      candidate = `${year}-${MONTHS[m[2]]}-${pad(m[1])}`;
    }
    return candidate;
  }

  m = lower.match(/^(?:[a-z]+day\s+)?([a-z]+)\s+(\d{1,2})$/);
  if (m && MONTHS[m[1]]) {
    let year = current.year;
    let candidate = `${year}-${MONTHS[m[1]]}-${pad(m[2])}`;
    if (candidate < todayISO()) {
      year += 1;
      candidate = `${year}-${MONTHS[m[1]]}-${pad(m[2])}`;
    }
    return candidate;
  }

  throw new Error(`Cannot parse date: ${dateText}`);
}

function parseTimeTo24(timeText) {
  const raw = String(timeText || '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (!raw) throw new Error('Missing time');

  let m = raw.match(/^(\d{1,2}):(\d{2})\s*(am|pm)$/);
  if (m) {
    let h = Number(m[1]);
    const min = Number(m[2]);
    if (h < 1 || h > 12 || min > 59) throw new Error(`Bad time: ${timeText}`);
    if (m[3] === 'pm' && h < 12) h += 12;
    if (m[3] === 'am' && h === 12) h = 0;
    return `${pad(h)}:${pad(min)}:00`;
  }

  m = raw.match(/^(\d{1,2})\s*(am|pm)$/);
  if (m) {
    let h = Number(m[1]);
    if (h < 1 || h > 12) throw new Error(`Bad time: ${timeText}`);
    if (m[2] === 'pm' && h < 12) h += 12;
    if (m[2] === 'am' && h === 12) h = 0;
    return `${pad(h)}:00:00`;
  }

  m = raw.match(/^(\d{1,2}):(\d{2})$/);
  if (m) {
    const h = Number(m[1]);
    const min = Number(m[2]);
    if (h > 23 || min > 59) throw new Error(`Bad time: ${timeText}`);
    return `${pad(h)}:${pad(min)}:00`;
  }

  throw new Error(`Bad time: ${timeText}`);
}

function prettyDate(dateISO) {
  const [y, mo, d] = dateISO.split('-');
  const names = {
    '01': 'January', '02': 'February', '03': 'March', '04': 'April',
    '05': 'May', '06': 'June', '07': 'July', '08': 'August',
    '09': 'September', '10': 'October', '11': 'November', '12': 'December'
  };
  return `${Number(d)} ${names[mo]} ${y}`;
}

function time24ToMinutes(time24) {
  const [h, m] = String(time24).split(':').map(Number);
  return h * 60 + m;
}

function minutesToTime24(totalMinutes) {
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  return `${pad(h)}:${pad(m)}:00`;
}

function addMinutesToTime(time24, mins) {
  return minutesToTime24(time24ToMinutes(time24) + mins);
}

function localDateTime(dateISO, time24) {
  return `${dateISO}T${time24}${TZ_OFFSET}`;
}

  const text = $('AI Agent').first().json.output || '';

  const WORK_START_HOUR = 10;
  const WORK_END_HOUR = 21;
  const BUFFER_MINUTES = 15;

  function getField(label) {
    const regex = new RegExp(label + ':\\s*(.+)', 'i');
    const match = text.match(regex);
    return match ? match[1].trim() : '';
  }

  function getServiceDurationMinutes(service) {
    const map = {
      manicure: 60,
      'gel manicure': 90,
      pedicure: 60,
      'gel pedicure': 90,
      haircut: 60,
      massage: 60,
      facial: 60
    };
    return map[String(service || '').toLowerCase().trim()] || 60;
  }

  const name = getField('Name');
  const service = getField('Service');
  const dateText = getField('Date');
  const timeText = getField('Time');

  const bookingDateISO = parseDateToISO(dateText);
  const bookingTime24 = parseTimeTo24(timeText);
  const duration_minutes = getServiceDurationMinutes(service);
  const total_minutes = duration_minutes + BUFFER_MINUTES;

  const startMinutes = time24ToMinutes(bookingTime24);
  const endMinutes = startMinutes + total_minutes;
  const workStartMinutes = WORK_START_HOUR * 60;
  const workEndMinutes = WORK_END_HOUR * 60;

  let booking_status = text.includes('BOOKING REQUEST READY') ? 'READY' : 'NOT_READY';

  if (booking_status === 'READY' && (startMinutes < workStartMinutes || endMinutes > workEndMinutes)) {
    booking_status = 'OUT_OF_HOURS';
  }

  const serviceEnd = addMinutesToTime(bookingTime24, duration_minutes);
  const calendarEnd = addMinutesToTime(bookingTime24, total_minutes);

  const start_datetime = localDateTime(bookingDateISO, bookingTime24);
  const service_end_datetime = localDateTime(bookingDateISO, serviceEnd);
  const end_datetime = localDateTime(bookingDateISO, calendarEnd);

  const search_after_datetime = localDateTime(bookingDateISO, minutesToTime24(Math.max(0, startMinutes - 180)));
  const search_before_datetime = localDateTime(bookingDateISO, minutesToTime24(Math.min(24 * 60 - 1, endMinutes + 180)));

  return [{
    json: {
      booking_status,
      name,
      service,
      date: bookingDateISO,
      pretty_date: prettyDate(bookingDateISO),
      time: bookingTime24,
      duration_minutes,
      buffer_minutes: BUFFER_MINUTES,
      total_minutes,
      start_datetime,
      end_datetime,
      service_end_datetime,
      search_after_datetime,
      search_before_datetime,
      timezone: TZ,
      timezone_offset: TZ_OFFSET,
      work_start: `${pad(WORK_START_HOUR)}:00`,
      work_end: `${pad(WORK_END_HOUR)}:00`,
      raw_ai_output: text
    }
  }];
} catch (error) {
  return [{ json: { booking_status: 'PARSE_ERROR', error: error.message } }];
}

