const telegram = $('Telegram Trigger').first().json;
const r = $('Find Current Appointment Event').first().json;

let messageText;
if (r.identity_mismatch) {
  messageText = `Sorry — I can't reschedule this appointment because it belongs to another Telegram account.`;
} else {
  messageText = `Sorry — I couldn't find your current appointment.

Name: ${r.name}
Current: ${r.current_pretty_date} at ${String(r.current_time).slice(0,5)}

Please check the details.`;
}

return [{json:{channel:'telegram',recipient_id:telegram.message.chat.id,message_text:messageText}}];
